#nullable enable
using HidDevice = YeManCC.Lighting.ILightingHidTransport;
using Color = YeManCC.Lighting.RgbColor;
namespace YeManCC.Lighting;

internal abstract class PinnedOneXProtocol
{
    public abstract bool SetLedColor(Color mainColor, Color secondaryColor, LEDLevel level, int speed = 100);
    public abstract bool SetLedBrightness(int brightness);
        public static byte[] BuildV1Command(byte cid, byte idx, IList<byte> cmd)
        {
            const int size = 64;
            byte[] buffer = new byte[size];

            int offset = 0;
            buffer[offset++] = cid;    // command id
            buffer[offset++] = 0x3F;   // constant
            buffer[offset++] = idx;    // index (0x01 in HHD)

            // leave last 2 bytes for [0x3F, cid]
            int maxCmdBytes = size - 5; // 3 header + 2 footer
            int cmdLen = Math.Min(cmd.Count, maxCmdBytes);

            for (int i = 0; i < cmdLen; i++)
                buffer[offset++] = cmd[i];

            buffer[size - 2] = 0x3F;
            buffer[size - 1] = cid;

            return buffer;
        }

        protected bool SendV1Brightness(HidDevice? device, int brightness, byte side = 0x00)
        {
            if (device is null || !device.IsConnected)
                return false;

            bool enabled = brightness > 0;

            byte level;
            if (!enabled || brightness <= 33)
                level = 0x01; // low
            else if (brightness <= 66)
                level = 0x03; // medium
            else
                level = 0x04; // high

            List<byte> cmd = new()
            {
                0xFD,               // brightness command
                side,               // side (0 = both)
                0x02,               // constant
                (byte)(enabled ? 1 : 0),
                0x05,               // constant
                level               // brightness level
            };
            byte[] payload = BuildV1Command(0xB8, 0x01, cmd);

            return device.Write(WithReportID(payload));
        }

        protected bool SendV1SolidColor(HidDevice? device, Color color, byte side = 0x00)
        {
            if (device is null || !device.IsConnected)
                return false;

            List<byte> cmd = new()
            {
                0xFE,           // solid-color mode
                side,           // side (0 = both sticks / light zones)
                0x02            // constant
            };
            // 18 repetitions of RGB (54 bytes)
            for (int i = 0; i < 18; i++)
            {
                cmd.Add(color.R);
                cmd.Add(color.G);
                cmd.Add(color.B);
            }

            // trailing [r, g] as in HHD
            cmd.Add(color.R);
            cmd.Add(color.G);

            byte[] payload = BuildV1Command(0xB8, 0x01, cmd);
            return device.Write(WithReportID(payload));
        }

        protected bool SendV1Rainbow(HidDevice? device, byte side = 0x00)
        {
            if (device is null || !device.IsConnected)
                return false;

            List<byte> cmd = new()
            {
                0x03,       // flowing mode
                side,
                0x02
            };
            byte[] payload = BuildV1Command(0xB8, 0x01, cmd);
            return device.Write(WithReportID(payload));
        }

    public static byte[] WithReportID(byte[] payload, byte reportID = 0x00, int reportLen = 64)
    {
        var buffer = new byte[1 + reportLen];
        buffer[0] = reportID;
        int len = Math.Min(payload.Length, reportLen);
        Buffer.BlockCopy(payload, 0, buffer, 1, len);
        return buffer;
    }
}

internal sealed class PinnedX1MiniProtocol : PinnedOneXProtocol
{
    private readonly HidDevice hidDevice;
    private readonly LEDLevel DynamicLightingCapabilities = LEDLevel.SolidColor | LEDLevel.LEDPreset | LEDLevel.Rainbow;
    internal PinnedX1MiniProtocol(HidDevice transport) => hidDevice = transport;
    public override bool SetLedColor(Color mainColor, Color secondaryColor, LEDLevel level, int speed = 100)
    {
        if (!DynamicLightingCapabilities.HasFlag(level))
            return false;

        return level switch
        {
            LEDLevel.SolidColor => SendV1SolidColor(hidDevice, mainColor, 0x00),
            LEDLevel.Rainbow => SendV1Rainbow(hidDevice, 0x00),
            _ => false
        };
    }

    public override bool SetLedBrightness(int brightness)
    {
        // X1 Mini uses the HID v1 vendor protocol (cid 0xB8, "brightness" command)
        return SendV1Brightness(hidDevice, brightness, 0x00);
    }
}
